#include <Arduino.h>
#include <TM1637Display.h>
#include <string.h>

TM1637Display display(4, 5);
const uint8_t sensors[3] = {2, 3, 7};
const unsigned long restockMs = 60000UL;
bool occupied[3] = {false, false, false};
bool reported[3] = {false, false, false};
unsigned long emptySince[3];
unsigned long records = 0;
bool recordsLocked = false;
char command[40];
uint8_t commandLength = 0;
unsigned long lastByte = 0;

void handleCommand() {
  command[commandLength] = '\0';
  if (strcmp(command, "STATUS") == 0) {
    for (uint8_t i = 0; i < 3; ++i) {
      Serial.print("Layer "); Serial.print(i + 1);
      Serial.println(occupied[i] ? ": occupied" : ": empty");
    }
    Serial.print("Records locked: "); Serial.println(recordsLocked ? 1 : 0);
  } else if (strcmp(command, "RESET") == 0) {
    unsigned long now = millis();
    for (uint8_t i = 0; i < 3; ++i) {
      emptySince[i] = now;
      reported[i] = false;
    }
    Serial.println("Timers reset");
  }
  commandLength = 0;
}

void setup() {
  Serial.begin(9600);
  for (uint8_t i = 0; i < 3; ++i) {
    pinMode(sensors[i], INPUT);
    emptySince[i] = millis();
  }
  pinMode(6, OUTPUT);
  pinMode(13, OUTPUT);
  display.setBrightness(7);
}

void loop() {
  unsigned long now = millis();
  bool next[3];
  uint8_t count = 0;
  for (uint8_t i = 0; i < 3; ++i) {
    next[i] = digitalRead(sensors[i]) == HIGH;
    if (next[i]) ++count;
  }
  recordsLocked = count == 3;
  for (uint8_t i = 0; i < 3; ++i) {
    if (next[i] != occupied[i]) {
      if (!next[i]) { emptySince[i] = now; reported[i] = false; }
      if (next[i] && !recordsLocked) ++records;
      occupied[i] = next[i];
    }
    if (occupied[i]) {
      reported[i] = false;
    } else if (!reported[i] && now - emptySince[i] > restockMs) {
      Serial.print("Layer "); Serial.print(i + 1);
      Serial.println(": restock needed");
      reported[i] = true;
    }
  }
  display.showNumberDec(count, false);
  digitalWrite(13, recordsLocked ? HIGH : LOW);
  if (recordsLocked) tone(6, 1000); else noTone(6);
  while (Serial.available()) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') {
      if (commandLength) handleCommand();
    } else if (commandLength < sizeof(command) - 1) {
      command[commandLength++] = c;
    }
  }
  if (commandLength && millis() - lastByte >= 20) handleCommand();
  delay(10);
}
